DROP VIEW IF EXISTS `Sales_vIndividualCustomer`;
CREATE VIEW `Sales_vIndividualCustomer` AS
select `p`.`BusinessEntityID` AS `BusinessEntityID`,`p`.`Title` AS `Title`,`p`.`FirstName` AS `FirstName`,`p`.`MiddleName` AS `MiddleName`,`p`.`LastName` AS `LastName`,`p`.`Suffix` AS `Suffix`,`pp`.`PhoneNumber` AS `PhoneNumber`,`pnt`.`Name` AS `PhoneNumberType`,`ea`.`EmailAddress` AS `EmailAddress`,`p`.`EmailPromotion` AS `EmailPromotion`,`at`.`Name` AS `AddressType`,`a`.`AddressLine1` AS `AddressLine1`,`a`.`AddressLine2` AS `AddressLine2`,`a`.`City` AS `City`,`sp`.`Name` AS `StateProvinceName`,`a`.`PostalCode` AS `PostalCode`,`cr`.`Name` AS `CountryRegionName`,`p`.`Demographics` AS `Demographics` from (((((((((`adventureworks`.`Person_Person` `p` join `adventureworks`.`Person_BusinessEntityAddress` `bea` on((`bea`.`BusinessEntityID` = `p`.`BusinessEntityID`))) join `adventureworks`.`Person_Address` `a` on((`a`.`AddressID` = `bea`.`AddressID`))) join `adventureworks`.`Person_StateProvince` `sp` on((`sp`.`StateProvinceID` = `a`.`StateProvinceID`))) join `adventureworks`.`Person_CountryRegion` `cr` on((`cr`.`CountryRegionCode` = `sp`.`CountryRegionCode`))) join `adventureworks`.`Person_AddressType` `at` on((`at`.`AddressTypeID` = `bea`.`AddressTypeID`))) join `adventureworks`.`Sales_Customer` `c` on((`c`.`PersonID` = `p`.`BusinessEntityID`))) left join `adventureworks`.`Person_EmailAddress` `ea` on((`ea`.`BusinessEntityID` = `p`.`BusinessEntityID`))) left join `adventureworks`.`Person_PersonPhone` `pp` on((`pp`.`BusinessEntityID` = `p`.`BusinessEntityID`))) left join `adventureworks`.`Person_PhoneNumberType` `pnt` on((`pnt`.`PhoneNumberTypeID` = `pp`.`PhoneNumberTypeID`))) where (`c`.`StoreID` is null)